    --color-canvas-white: #f9fafc;
    --color-pure-white: #ffffff;
    --color-storm: #4a5465;
    --font-louize: 'Playfair Display', 'Georgia', serif;
    --font-nunito: 'Nunito', 'Helvetica Neue', sans-serif;
  }

  .hero-tagline {
    background: var(--color-canvas-white);
    padding: 48px 40px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0;
    font-family: var(--font-nunito);
    max-width: 600px;
    box-sizing: border-box;
  }

  .hero-tagline__heading {
    font-family: var(--font-louize);
    font-weight: 400;
    font-size: 60px;
    line-height: 0.9;
    letter-spacing: -0.04em;
    color: var(--color-midnight-ink);
    text-align: center;
    margin: 0 0 28px 0;
  }

  .hero-tagline__body {
    font-family: var(--font-nunito);
    font-size: 18px;
    line-height: 1.8;
    color: var(--color-storm);
    text-align: center;
    margin: 0;
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    align-items: center;
    gap: 6px;
    font-weight: 400;
  }

  .tag {
    display: inline-flex;
    align-items: center;
    padding: 2px 14px;
    border-radius: 36px;
