    background: var(--color-canvas-white);
    padding: 48px 40px;
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    justify-content: center;
    align-items: center;
    max-width: 600px;
    box-sizing: border-box;
  }

  .platform-btn {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 10px 20px;
    border-radius: 100px;
    border: 1px solid var(--color-slate);
    background: transparent;
    color: var(--color-slate);
    font-family: var(--font-nunito);
    font-size: 15px;
    font-weight: 600;
    line-height: 1.4;
    letter-spacing: 0.01em;
    text-decoration: none;
    cursor: pointer;
    transition: border-color 0.2s, color 0.2s;
    white-space: nowrap;
  }

  .platform-btn:hover {
    border-color: #4a5465;
    color: #4a5465;
  }

  .platform-btn__icon {
    width: 20px;
    height: 20px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
  }

  /* Apple icon */
  .icon-apple {
    width: 18px;
    height: 18px;
    background: var(--color-slate);
    border-radius: 3px;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  /* Chrome icon — colored circles approximation */
  .icon-chrome {
    width: 18px;
    height: 18px;
    border-radius: 50%;
    background: conic-gradient(#ea4335 0deg 120deg, #34a853 120deg 240deg, #4285f4 240deg 360deg);
    position: relative;
    overflow: hidden;
  }
  .icon-chrome::after {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 7px;
    height: 7px;
    background: white;
    border-radius: 50%;
  }

  /* Play store icon */
  .icon-play {
    width: 18px;
    height: 18px;
    position: relative;
  }

  .platform-section-label {
    width: 100%;
    text-align: center;
    font-family: var(--font-nunito);
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--color-slate);
    margin-bottom: 8px;
  }
</style>

<div class="platform-buttons">
