  {
    "html": "<style>
  :root {
    --color-parchment-card: #f3f0e7;
    --color-pure-white: #ffffff;
    --color-deep-slate: #3a475a;
    --color-chalk: #a6a8aa;
    --color-storm: #4a5465;
    --color-steel: #717286;
    --color-mist: #e2e2e2;
    --color-ember-orange: #ff5924;
    --color-canvas-white: #f9fafc;
    --shadow-sm: rgba(140, 142, 151, 0.32) 0px 4px 7px -4px;
    --font-inter: 'Inter', 'Helvetica Neue', sans-serif;
    --font-louize: 'Playfair Display', 'Georgia', serif;
    --font-nunito: 'Nunito', 'Helvetica Neue', sans-serif;
  }

  .feature-section {
    background: var(--color-canvas-white);
    padding: 48px 32px;
    max-width: 600px;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    gap: 24px;
    align-items: flex-start;
  }

  .feature-section__eyebrow {
    font-family: var(--font-nunito);
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--color-ember-orange);
    margin: 0;
  }

  .feature-section__heading {
    font-family: var(--font-louize);
    font-weight: 400;
    font-size: 42px;
    line-height: 1.1;
    letter-spacing: -0.03em;
    color: var(--color-midnight-ink, #1a1a1a);
    margin: 0;
  }

  .checklist-card {
    background: var(--color-pure-white);
    border-radius: 16px;
    padding: 32px 36px;
    width: 100%;
    box-sizing: border-box;
    box-shadow: var(--shadow-sm);
  }

  .checklist-card__title {
    font-family: var(--font-inter);
    font-size: 17px;
    font-weight: 400;
    line-height: 1.5;
    color: var(--color-deep-slate);
    margin: 0 0 20px 0;
  }

  .checklist-card__list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 12px;
  }

  .checklist-item {
    display: flex;
    align-items: center;
    gap: 12px;
    font-family: var(--font-inter);
    font-size: 17px;
    line-height: 1.4;
    font-weight: 400;
  }

  .checklist-item--done {
    color: var(--color-chalk);
    text-decoration: line-through;
    text-decoration-color: var(--color-chalk);
  }

  .checklist-item--active {
    color: var(--color-deep-slate);
  }

  .checkbox {
    width: 20px;
    height: 20px;
    border-radius: 50%;
    border: 1.5px solid var(--color-mist);
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    background: transparent;
  }

  .checkbox--checked {
    border-color: var(--color-chalk);
    background: transparent;
  }

  .checkbox--checked::after {
    content: '';
    display: block;
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: var(--color-chalk);
  }

  .card-wrapper {
    background: var(--color-parchment-card);
    border-radius: 16px;
    padding: 28px;
    width: 100%;
    box-sizing: border-box;
  }
</style>

<div class="feature-section">
  <p class="feature-section__eyebrow">Your Private Oasis</p>
  <h2 class="feature-section__heading">A treasure trove of ideas, inspiration &amp; references</h2>

  <div class="card-wrapper">
    <div class="checklist-card">
      <p class="checklist-card__title">Dinner with friends tonight, so remember to buy ingredients:</p>
      <ul class="checklist-card__list">
        <li class="checklist-item checklist-item--done">
          <span class="checkbox checkbox--checked"></span>
          Rigatoni pasta
        </li>
        <li class="checklist-item checklist-item--active">
          <span class="checkbox"></span>
          Basil from Tom's garden
        </li>
        <li class="checklist-item checklist-item--done">
          <span class="checkbox checkbox--checked"></span>
          Tomatoes from Taylor's
        </li>
        <li class="checklist-item checklist-item--active">
          <span class="checkbox"></span>
          Olive oil
        </li>
        <li class="checklist-item checklist-item--active">
          <span class="checkbox"></span>
          Parmigiano reggiano
        </li>
        <li class="checklist-item checklist-item--done">
          <span class="checkbox checkbox--checked"></span>
          That nice porto wine
        </li>
      </ul>
    </div>
  </div>
</div>",
